#[test]
fn canonical_headless_media_is_registered() {
 let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
 let raw: serde_json::Value = serde_json::from_slice(&fs::read(root.join("test/cmocka/build/test-graph.json")).unwrap()).unwrap();
 let expected = expected();
 for name in CASES { for section in ["targets", "tests"] { assert_eq!(raw[section][name], expected[section][name], "{section}/{name}"); } }
 for fragment in ["test_startup_diagnostics", "test_media_source_options_lifetime", "test_media_status_threading", "test_media_cached_paused_seek", "test_ffmpeg_restart_close"] {
 let text = fs::read_to_string(root.join(format!("test/cmocka/tests.d/{fragment}.cmake"))).unwrap();
 assert!(text.contains("test-graph.json")); assert!(!text.contains("add_executable(")); assert!(!text.contains("add_test("));
 }
}
#[test]
fn canonical_headless_media_guards() {
 let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
 let mut graph = Graph::load(&root.join("test/cmocka/build/test-graph.json")).unwrap();
 graph.targets.retain(|n,_| CASES.contains(&n.as_str())); graph.tests.retain(|n,_| CASES.contains(&n.as_str()));
 assert_eq!(graph.targets.len(), 6);
 for os in ["OS_LINUX", "OS_FREEBSD", "OS_OPENBSD", "OS_WINDOWS", "OS_MACOS"] { for owner in [false,true] { for glad in [false,true] {
 let facts = [("OS_LINUX".into(),os=="OS_LINUX"),("OS_FREEBSD".into(),os=="OS_FREEBSD"),("OS_OPENBSD".into(),os=="OS_OPENBSD"),("MSVC".into(),os=="OS_WINDOWS"),("HAVE_MEDIA_PLAYBACK_TEST_OWNER".into(),owner),("HAVE_STARTUP_GLAD".into(),glad)].into();
 let selected = graph.select(&facts).unwrap();
 let count = usize::from(os=="OS_LINUX")*(1+usize::from(glad)+2*usize::from(owner))+2*usize::from(owner);
 assert_eq!(selected.targets.len(),count,"{os}/{owner}/{glad}"); assert_eq!(selected.tests.len(),count);
 }}}
}
